package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.Support;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalGroupedLocalRounds.Certificate;
import org.kanger.ContextWitnessResultTransport.*;

/** Certified transfer keeps exact data/parameter obligations inside a fresh original transport budget. */
public final class ContextUniversalCertifiedTransferSessionRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static void failed(SessionTransfer t,String why){ConstraintTransfer r=t.transfer;require(!r.transferred&&r.output==null&&r.local==null&&r.privateAfter==null&&r.bindings==null&&r.certificate==null&&t.metrics.entries==0,why+": "+r.reason);}
    static SessionTransfer transfer(Certificate c,int depth,int work,int cap){return ContextWitnessResultTransport.transferConstraintsCertifiedWithValidationReuse(c,depth,work,cap);}
    static SessionTransfer yes(Certificate c){SessionTransfer t=transfer(c,16,WORK,4096);require(t.transfer.transferred&&t.metrics.entries==0&&t.metrics.hits>0&&t.metrics.verified>0,t.transfer.reason);require(t.transfer.certificate==c&&t.transfer.proof==c.output&&t.transfer.bindings.coverage==c.output,"actual certificate/Origin coverage retained");require(ContextUniversalSignedProductAudit.bind(c.output,t.transfer,65536,WORK).bound,"fresh independent product correspondence");return t;}
    static void compare(ConstraintTransfer a,ConstraintTransfer b){require(a.transferred&&b.transferred&&a.proof==b.proof&&a.before==b.before&&a.privateBefore==b.privateBefore&&a.commonChanged==b.commonChanged&&a.localChanged==b.localChanged,"same actual source/input frame/change flags");require(ContextWitnessResultTransport.sameContents(a.output,b.output,WORK)&&ContextWitnessResultTransport.sameContents(a.local,b.local,WORK),"exact signed/whole-Source/depth minima and retained inputs equal");require(a.privateAfter==null?b.privateAfter==null:b.privateAfter!=null&&a.privateAfter.sources.equals(b.privateAfter.sources)&&a.privateAfter.declarations.equals(b.privateAfter.declarations),"private physical source/declaration inventories equal");}
    static void cases()throws Exception {
        ContextUniversalGroupedChainAuditRunner.Fixture f=new ContextUniversalGroupedChainAuditRunner.Fixture(false,true);Certificate c=f.trace.history.get(0).certificates.get(Cut.of(f.b));ConstraintTransfer original=ContextWitnessResultTransport.transferConstraintsCertified(c,16,WORK);SessionTransfer scoped=yes(c);compare(original,scoped.transfer);require(scoped.transfer.output.items.stream().anyMatch(i->i.atom.predicate.equals("r"))&&scoped.transfer.output.items.stream().noneMatch(i->i.atom.predicate.equals("a")||i.atom.predicate.equals("hidden")),"private parameter result crosses without raw witness/bundle publication");
        Certificate privateCert=f.trace.history.get(1).certificates.get(Cut.of(f.a));SessionTransfer privateTransfer=yes(privateCert);compare(ContextWitnessResultTransport.transferConstraintsCertified(privateCert,16,WORK),privateTransfer.transfer);require(privateTransfer.transfer.privateAfter!=null&&privateTransfer.transfer.local!=privateTransfer.transfer.output,"private receiver retained separately");
        failed(transfer(c,0,WORK,4096),"fact depth refusal no certificate/parameter/product prefix");SessionTransfer tiny=transfer(c,16,1,4096);failed(tiny,"fresh work1 cannot exploit prior success");require(tiny.transfer.reason.contains("Witness transport work limit")&&tiny.metrics.work==2,"original witness counter/message includes failing second attempt");failed(transfer(null,16,WORK,4096),"missing actual certificate");SessionTransfer cap1=transfer(c,16,WORK,1);require(cap1.transfer.transferred&&cap1.metrics.peakEntries==1&&cap1.metrics.capacityBypass>0&&cap1.metrics.entries==0,"capacity1 real-check fallback");compare(original,cap1.transfer);
        ContextUniversalFrozenConstraints.Proof grouped=c.output.proofs.stream().filter(p->p.grouped!=null).findFirst().get();java.lang.reflect.Field support=grouped.getClass().getDeclaredField("support");support.setAccessible(true);Support real=grouped.support;support.set(grouped,new Support(real.sources,real.depth+1));try{failed(transfer(c,16,WORK,4096),"new invocation rejects forged grade after prior successful transfer");}finally{support.set(grouped,real);}
        java.lang.reflect.Field manifest=c.output.getClass().getDeclaredField("groupedInputs");manifest.setAccessible(true);Object actual=manifest.get(c.output);manifest.set(c.output,Collections.emptyList());try{failed(transfer(c,16,WORK,4096),"missing full manifest not inherited from earlier session");}finally{manifest.set(c.output,actual);}
        java.lang.reflect.Field bindings=ConstraintTransfer.class.getDeclaredField("bindings");bindings.setAccessible(true);Object receipt=bindings.get(scoped.transfer);bindings.set(scoped.transfer,null);try{require(!ContextUniversalSignedProductAudit.bind(c.output,scoped.transfer,65536,WORK).bound,"separate product audit refuses missing parameter sidecar even after successful transfer");}finally{bindings.set(scoped.transfer,receipt);}
        require(ContextUniversalSignedProductAudit.bind(c.output,scoped.transfer,65536,WORK).bound,"restored actual transfer independently valid");
    }
    static void refutation()throws Exception {Snapshot x=ContextUniversalGroupedRoundsRunner.bind(true,"!p(1);"),a=ContextUniversalGroupedRoundsRunner.bind(false,"!@u p(u)&&b(u)->r(u);"),b=ContextUniversalGroupedRoundsRunner.bind(false,"!b(1); !~r(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);ContextUniversalCompoundExchange.Exchange e=ContextUniversalGroupedRoundsRunner.exchange(x,Arrays.asList(a,b),p,Collections.emptyMap());ContextUniversalFrozenConstraints.Result base=ContextUniversalFrozenConstraints.closeSignedCompounds(ContextUniversalCompoundExchangeRunner.rows(x,b),p,null,null,e,16,16,512,256,WORK);require(base.closed&&base.xRefuted,base.reason);ContextUniversalGroupedLocalRounds.Closure local=ContextUniversalGroupedLocalRounds.runWithValidationReuse(base,ContextUniversalGroupedRoundsRunner.local(),4096);require(local.stable&&local.output.output.xRefuted,local.reason);failed(transfer(local.output,16,WORK,4096),"authenticated refutation grants no transfer products");}
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("certified-transfer-session-").toString());cases();refutation();System.out.println("CONTEXT_UNIVERSAL_CERTIFIED_TRANSFER_SESSION_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
